import { groupedHead, columnCount, groupStarts, attentionMark, ciMark, packMark, commitGraph,
         segmentBar, el, ago, duration, reasonNodes, LEVEL_GLYPH, STATE_ORDER, STATE_COLOR,
         STATE_UI, OUTCOME_COLOR, repoLink } from './ui.mjs';
import { attentionBreakdown } from './fleet.mjs';

document.getElementById('s').textContent = await (await fetch('./_render.css')).text();
const MODE = new URLSearchParams(location.search).get('mode') ?? 'after';
document.getElementById('cap').textContent = MODE === 'before' ? 'BEFORE — prose column' : 'AFTER — folded to a mark';

const GROUPS = [
  ['', ['Member']],
  ['Activity', ['Commits']],
  ['Waiting on a person', ['Est.', 'What it is', 'Issues', 'Pull requests']],
  ['Claudinite', ['Packs', 'Queue', 'Recent outcomes', 'Scheduler']],
];
const COLS = columnCount(GROUPS), STARTS = groupStarts(GROUPS);
const now = Date.now();
const MEMBERS = [
  { repo: 'missingbulb/hitbut', counts: { broken: 2, decisions: 4, actions: 9, approvals: 1 }, min: 133, issues: 13, prs: 33, packs: 14, level: 'critical' },
  { repo: 'missingbulb/Claudinite', counts: { broken: 1, decisions: 2, actions: 5, tripping: 2, approvals: 7 }, min: 78, issues: 49, prs: 39, packs: 9, level: 'critical' },
  { repo: 'missingbulb/ClaudiniteWebsite', counts: { broken: 3, decisions: 6, actions: 2 }, min: 85, issues: 19, prs: 38, packs: 10, level: 'critical' },
  { repo: 'missingbulb/quiet-one', counts: {}, min: 0, issues: 0, prs: 1, packs: 6, level: 'ok' },
];
const body = groupedHead(document.getElementById('fleet'), GROUPS);
const banded = (cells) => cells.map((c, i) => { if (STARTS.includes(i)) c.classList.add('group-start'); return c; });
for (const m of MEMBERS) {
  const needs = attentionBreakdown(m.counts);
  const what = MODE === 'before'
    ? el('td', {}, needs.length
        ? [el('div', { className: 'needs' }, needs.map((r) => el('div', { className: `warn ${r.level}`, textContent: `${LEVEL_GLYPH[r.level]} ${r.text}` })))]
        : [el('span', { className: 'sub', textContent: 'nothing waiting' })])
    : el('td', {}, [attentionMark(needs)]);
  const cells = [
    el('td', { className: 'member-cell' }, [el('div', { className: 'member' }, [
      ciMark({ label: 'passing', cls: 'ok' }, '2h'),
      el('div', {}, [el('a', { className: 'name', href: '#', textContent: m.repo.split('/')[1] }),
                     el('div', { className: 'sub' }, [repoLink(m.repo)])]),
    ])]),
    el('td', { className: 'nw' }, [commitGraph(Array.from({ length: 90 }, (_, i) => (i % 7 ? 0 : 3)), { note: 'last 2h' })]),
    el('td', { className: 'num nw' }, [el('div', { className: 'est num', textContent: m.min ? String(m.min) : '—' }), el('div', { className: 'sub', textContent: m.min ? 'min' : '' })]),
    what,
    el('td', { className: 'num nw' }, [el('div', { textContent: String(m.issues) }), el('div', { className: 'sub', textContent: 'oldest 15d' })]),
    el('td', { className: 'num nw' }, [el('div', { textContent: String(m.prs) }), el('div', { className: 'sub', textContent: 'oldest 12d' })]),
    el('td', { className: 'nw' }, [packMark(m.packs, { state: 'current', engineVersion: '60902.1' })]),
    el('td', {}, [segmentBar(STATE_ORDER.map((st, i) => [STATE_UI[st].label, i === 4 ? 16 : 0, STATE_COLOR[st]]), { width: 92 }), el('div', { className: 'sub', textContent: '16 needs human' })]),
    el('td', {}, [segmentBar([['done', 9, OUTCOME_COLOR.done]], { width: 92 }), el('div', { className: 'sub', textContent: '2h ago' })]),
    el('td', { className: 'nw' }, [el('div', { className: 'sub', textContent: 'passing' }), el('div', { className: 'sub', textContent: '3h ago' })]),
  ];
  body.append(el('tr', { className: `std lvl-${m.level}` }, banded(cells)));
}
</script></body></html>
